{
  "template": "trigger"
}

namespace walk;
table Settings { seed:ulong; walkers:ulong; steps:ulong; }
table Outputs { walk:Settings (required); }
root_type Outputs;

{
  "template": "input",
  "params": [
    {
      "name": "seed",
      "type": "uint64",
      "data": 7
    },
    {
      "name": "walkers",
      "type": "uint64",
      "data": 400
    },
    {
      "name": "steps",
      "type": "uint64",
      "data": 200
    }
  ]
}

namespace walk;
// Positions of every walker after every step, walker-major (walkers × (steps + 1)).
table Walks { walkers:ulong; steps:ulong; positions:[double]; }
table Outputs { walks:Walks (required); }
root_type Outputs;

{ pkgs, inputs, params }:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
    inherit sdk;
    src = ./src;
    packages = ps: [ ps.numpy ];
  };
}

{
  "language": "python",
  "inputs": [
    {
      "name": "walk"
    }
  ]
}

{
  "template": "fork",
  "params": [
    {
      "name": "branches",
      "type": "string[]",
      "data": [
        "summary",
        "diffusion",
        "explore",
        "spread"
      ]
    }
  ]
}

